{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a close retinoid analogue, has an absolute oral bioavailability of approximately 60% (range 36-95%) after a 50 mg oral dose with food versus IV infusion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Etretinate, a lipophilic retinoid ester, has an absolute oral bioavailability of 44 ± 14% (range 30-70%) after oral capsules versus IV administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin (13-cis-retinoic acid) has a systemic bioavailability of 40% at 1 mg/kg/day in patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Tretinoin (all-trans-retinoic acid) oral bioavailability is approximately 50% in humans.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a retinoid amide (fenretinide-like). Structurally related retinoids—tretinoin, isotretinoin, acitretin, and etretinate—have oral bioavailability values of about 40-60%, all above the 20% threshold. No affirmative quantitative evidence supports F < 20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide itself is provided.",
    "Food effects and formulation dependence for the query molecule are not directly evidenced.",
    "The impact of the p-hydroxyphenyl amide modification on retinoid absorption is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

